#!/bin/bash
# Generated by Claude Fable 5.1 (Anthropic), 2026-10-04
# Build a new FISH overlay image from the previous one: apply a patch script inside a container, colcon-build the
# named overlay packages, commit.  (Replaces the per-image build_fwNN.sh that lived in a scratch directory.)
# Usage: docker/overlay_patches/build_overlay.sh <new_tag> <base_tag> <patch.py|-> <pkg> [pkg ...]
#   e.g. build_overlay.sh fishwait19 fishwait18 fishwait19_identity.py tracetools cyclonedds rmw_cyclonedds_cpp
# Extra shell in the container before the patch: PRE_CMD='...'; after the build: POST_CMD='...' (repo scripts are at /fish_scripts).  Log: /tmp/build_<new_tag>.log (or $LOG).
# FORKS (2026-10-05): a tag "fork-<name>" is a side branch of the image lineage (e.g. Autoware recompiled against the
# overlay headers). Fork images get the label fish.lineage=fork and a marker file; a mainline tag (fishwaitNN) is
# never built on a fork base, and scripts/autoware_runs/run_overhead_modes.sh refuses fork images unless
# FISH_ALLOW_FORK=1 — so no campaign runs on recompiled binaries by accident.
set -u
NEW=$1; BASE=$2; PATCH=$3; shift 3; PKGS="$*"
HERE=$(cd "$(dirname "$0")" && pwd); LOG=${LOG:-/tmp/build_$NEW.log}; C=build_$NEW
P=autoware-dev-trt-a1000
BASE_LINEAGE=$(docker image inspect -f '{{index .Config.Labels "fish.lineage"}}' $P-$BASE:latest 2>/dev/null)
case "$NEW" in
  fork-*) FORK=1 ;;
  *) FORK=0; [ "$BASE_LINEAGE" = fork ] && { echo "REFUSED: $BASE is a fork image; a mainline tag ($NEW) must not be built on it" | tee "$LOG"; exit 2; } ;;
esac
docker rm -f $C >/dev/null 2>&1
docker run -d --name $C --entrypoint bash -v "$HERE":/patches:ro -v "$HERE/../../scripts":/fish_scripts:ro $P-$BASE:latest -c 'sleep 14400' >/dev/null
{
  echo "=== $(date +%T) $BASE → $NEW: patch=$PATCH pkgs=$PKGS"
  [ -n "${PRE_CMD:-}" ] && docker exec $C bash -c "$PRE_CMD"       # e.g. clone an extra package into the overlay workspace
  [ "$PATCH" != "-" ] && docker exec $C python3 /patches/$PATCH
  [ -n "$PKGS" ] && docker exec $C bash -c "source /opt/ros/humble/setup.bash && source /opt/autoware/setup.bash && source /root/trace_overlay_ws/install/setup.bash && cd /root/trace_overlay_ws && colcon build --packages-select $PKGS --cmake-args -DCMAKE_BUILD_TYPE=RelWithDebInfo -DBUILD_TESTING=OFF 2>&1 | tail -25"
  # the shim is rebuilt against the (possibly changed) tracetools
  docker exec $C bash -c 'T=/root/trace_overlay_ws/install/tracetools; cp $T/lib/libfish_gomp_shim.so /tmp/shim_old.so 2>/dev/null; gcc -shared -fPIC -O2 -o $T/lib/libfish_gomp_shim.so /patches/fish_gomp_shim.c -I$T/include/tracetools -L$T/lib -ltracetools -ldl -Wl,--no-as-needed -l:libgomp.so.1 && echo SHIM_OK; source /opt/ros/humble/setup.bash; source /root/trace_overlay_ws/install/setup.bash; echo "old shim:"; bash /patches/test_gomp_shim.sh /tmp/shim_old.so | sed "s/SHIM_TEST_/OLD_SHIM_TEST_/"; echo "new shim:"; bash /patches/test_gomp_shim.sh $T/lib/libfish_gomp_shim.so'
  # lock shim (fishwait24+): built only when the overlay's tracetools has the fish_lock event
  docker exec $C bash -c 'T=/root/trace_overlay_ws/install/tracetools; grep -q fish_lock $T/include/tracetools/tracetools/tracetools.h || exit 0; gcc -shared -fPIC -O2 -o $T/lib/libfish_lock_shim.so /patches/fish_lock_shim.c -I$T/include/tracetools -L$T/lib -ltracetools -ldl -lpthread && echo LOCKSHIM_OK || echo "SHIM_TEST_FAIL lock: build"; source /opt/ros/humble/setup.bash; source /root/trace_overlay_ws/install/setup.bash; bash /patches/test_lock_shim.sh $T/lib/libfish_lock_shim.so'
  [ -n "${POST_CMD:-}" ] && docker exec $C bash -c "$POST_CMD"
  echo "=== $(date +%T) build step done"
} > "$LOG" 2>&1
if grep -q "all patches applied\|^=== .* patch=- " "$LOG" && ! grep -q "Failed   <<<\|Aborted  <<<\|AssertionError\|^SHIM_TEST_FAIL" "$LOG" && grep -q "^SHIM_TEST_OK" "$LOG"; then
  LABELS=(); if [ "$FORK" = 1 ]; then
    docker exec $C bash -c "printf 'FISH FORK image %s (base %s, patch %s, built %s)\nNot part of the fishwaitNN line: Autoware packages are recompiled against the overlay headers (see /root/trace_overlay_ws/fish_rebuilt_packages.json).\nDo not use for campaigns that are compared with mainline images.\n' '$NEW' '$BASE' '$PATCH' \"\$(date -u +%FT%TZ)\" > /root/trace_overlay_ws/FISH_FORK.txt"
    LABELS=(--change "LABEL fish.lineage=fork" --change "LABEL fish.fork.base=$BASE" --change "LABEL fish.fork.patch=$PATCH")
  fi
  docker commit --change 'CMD ["bash","-c","sleep 10800"]' --change 'ENTRYPOINT ["/ros_entrypoint.sh"]' --change 'WORKDIR /autoware' "${LABELS[@]}" $C $P-$NEW:latest >> "$LOG" 2>&1 && echo COMMITTED >> "$LOG"
else
  echo "NOT COMMITTED (patch or build failed)" >> "$LOG"
fi
docker rm -f $C >/dev/null 2>&1; echo DONE >> "$LOG"
